const seed={products:[{id:'p1',name:'Наклейки «Капибара»',description:'Набор из 6 наклеек для любимых вещей.',price:80,quantity:12,art:'stickers',image:''},{id:'p2',name:'Блокнот для идей',description:'Чистые страницы для больших изобретений.',price:120,quantity:8,art:'book',image:''},{id:'p3',name:'Брелок «Капибара»',description:'Маленький друг для рюкзака или ключей.',price:150,quantity:6,art:'key',image:''},{id:'p4',name:'Набор карандашей',description:'12 цветов для самых ярких задумок.',price:100,quantity:10,art:'pencils',image:''},{id:'p5',name:'Кружка «Всё получится»',description:'Для тёплого чая и новых открытий.',price:250,quantity:4,art:'mug',image:''},{id:'p6',name:'Капибара-плюш',description:'Мягкая капибара, которую хочется обнять.',price:500,quantity:3,art:'plush',image:''}],showcases:[{id:'s1',name:'Осенняя витрина',items:['p1','p2','p3','p4','p5','p6']},{id:'s2',name:'Маленькие награды',items:['p1','p3','p4']}],published:'s1'};
let db;try{db=JSON.parse(localStorage.getItem('capybara-demo-v1'))||structuredClone(seed);if(!Array.isArray(db.products)||!Array.isArray(db.showcases))throw Error();}catch{db=structuredClone(seed)}
let page='account',selected=1,query='',admin=false,adminTab='products',draftItems=[],dragId=null,editingShowcase=null,toastTimer;
function save(next){try{localStorage.setItem('capybara-demo-v1',JSON.stringify(next));db=next;return true}catch{toast('Не удалось сохранить: хранилище браузера недоступно или заполнено.');return false}}
function mutate(fn){const next=structuredClone(db);fn(next);return save(next)}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function capy(){return '<g fill="#be956f" stroke="#8b6649" stroke-width="2"><ellipse cx="104" cy="97" rx="48" ry="32"/><rect x="68" y="111" width="13" height="21" rx="6"/><rect x="121" y="111" width="13" height="21" rx="6"/><ellipse cx="141" cy="84" rx="33" ry="27"/><circle cx="122" cy="61" r="8"/><circle cx="151" cy="80" r="2" fill="#45362b" stroke="none"/><path d="M167 92h-10" fill="none"/><path d="M169 80h3"/></g>'}
function art(p){if(p.image)return '<img src="'+esc(p.image)+'" alt="'+esc(p.name)+'">';let content='';switch(p.art){case 'book':content='<g transform="rotate(-10 110 85)"><rect x="58" y="17" width="103" height="143" rx="8" fill="#698364"/><path d="M71 17v143" stroke="#506b4d" stroke-width="3"/><rect x="87" y="48" width="56" height="61" rx="3" fill="#f5edda"/><path d="M98 68h33M98 78h23" stroke="#a59c81" stroke-width="2"/><text x="115" y="98" text-anchor="middle" font-size="9" fill="#8a826d">ИДЕИ</text></g>';break;case 'key':content='<circle cx="110" cy="30" r="17" fill="none" stroke="#a9aaa0" stroke-width="5"/><path d="M110 46v20" stroke="#a9aaa0" stroke-width="5"/><g transform="translate(-6 9)">'+capy()+'</g>';break;case 'pencils':content='<rect x="61" y="48" width="98" height="111" rx="4" fill="#d9bea0"/>';['#a76550','#d1a955','#779476','#6b8b94','#b98caa','#685f82'].forEach((c,i)=>content+='<path d="M'+(70+i*15)+' 70v-42l5-15 5 15v42z" fill="'+c+'"/><path d="M'+(70+i*15)+' 28l5-15 5 15" fill="#e6d7b9"/>');content+='<rect x="61" y="79" width="98" height="50" fill="#ebdfc9"/><text x="110" y="109" text-anchor="middle" font-size="12" fill="#8b795f">12 ЦВЕТОВ</text>';break;case 'mug':content='<ellipse cx="108" cy="146" rx="64" ry="8" fill="#d9d4c7"/><path d="M155 63h15c31 0 31 57 0 57h-15" fill="none" stroke="#b1bc9b" stroke-width="13"/><path d="M55 47h108v79q0 19-20 19H75q-20 0-20-19z" fill="#d4dec4"/><ellipse cx="109" cy="47" rx="54" ry="10" fill="#e8eddc"/><ellipse cx="109" cy="47" rx="44" ry="5" fill="#b9c4a6"/><text x="109" y="88" text-anchor="middle" fill="#6a7c54" font-size="12">ВСЁ</text><text x="109" y="108" text-anchor="middle" fill="#6a7c54" font-size="11">ПОЛУЧИТСЯ</text>';break;case 'stickers':content='<g transform="rotate(-10 105 90)"><rect x="34" y="20" width="142" height="134" rx="8" fill="#fffdf7" stroke="#ddd5c8"/>'+capy()+'<circle cx="58" cy="46" r="15" fill="#d5e2bd"/><path d="m58 35 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1z" fill="#8da66b"/><circle cx="145" cy="129" r="12" fill="#edcf8c"/></g>';break;default:content='<ellipse cx="110" cy="144" rx="71" ry="10" fill="#dfd7ca"/><g transform="translate(-8 -7) scale(1.1)">'+capy()+'</g>'}return '<svg viewBox="0 0 220 175" role="img" aria-label="'+esc(p.name)+'">'+content+'</svg>'}
function initials(name){return name.split(' ').slice(0,2).map(n=>n[0]).join('')}
function normalize(v){return v.toLocaleLowerCase('ru').replace(/ё/g,'е')}
function listChildren(){const matches=children.filter(c=>normalize(c.name).includes(normalize(query.trim())));$('#child-list').innerHTML=matches.map(c=>'<button class="child '+(selected===c.id?'selected':'')+'" data-child="'+c.id+'" aria-pressed="'+(selected===c.id)+'"><span class="avatar">'+initials(c.name)+'</span><span><strong>'+esc(c.name.split(' ').slice(0,2).join(' '))+'</strong><small>'+esc(c.name.split(' ')[2])+'</small></span><span class="chevron">›</span></button>').join('')||'<div class="empty">Никого не нашли.<br>Попробуйте другую часть ФИО.</div>';$('#child-count').textContent=matches.length+' из '+children.length}
function profile(){const c=children.find(c=>c.id===selected),balance=c.history.reduce((s,t)=>s+t[2],0);$('#profile').innerHTML='<section class="panel"><div class="profile-head"><span class="avatar">'+initials(c.name)+'</span><div><h2>'+esc(c.name)+'</h2><p>Карточка ребёнка</p></div></div><div class="balance"><div><div class="balance-label">Текущий счёт</div><div class="balance-value">'+balance.toLocaleString('ru')+'<small>КК</small></div></div><div class="coin" aria-hidden="true">КК</div></div><div class="groups"><span class="muted">Твои группы</span>'+c.groups.map(g=>'<span class="group">'+esc(g)+'</span>').join('')+'</div></section><section class="panel history"><div class="history-heading"><h2>История начислений и списаний</h2><span class="muted">'+c.history.length+' операций</span></div><div class="transactions">'+c.history.map(t=>'<div class="transaction"><span class="operation '+(t[2]<0?'minus':'')+'">'+(t[2]<0?'↗':'↙')+'</span><div><strong>'+esc(t[1])+'</strong><small>'+new Date(t[0]+'T12:00:00Z').toLocaleDateString('ru',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'})+'</small></div><div class="amount '+(t[2]<0?'negative':'')+'">'+(t[2]>0?'+':'−')+Math.abs(t[2])+'<small>КК</small></div></div>').join('')+'</div></section>'}
function productCard(p){return '<article class="product"><div class="product-art">'+art(p)+'</div><div class="product-body"><h3>'+esc(p.name)+'</h3><p>'+esc(p.description)+'</p><div class="product-bottom"><span class="price">'+p.price+' <small>КК</small></span><span class="stock">'+(p.quantity?'В наличии: '+p.quantity+' шт.':'Нет в наличии')+'</span></div></div></article>'}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#admin-entry').textContent=admin?(page==='admin'?'Админ · Выйти ↗':'Панель администратора ↗'):'Вход для админа ↗';if(page==='account'){$('#app').innerHTML='<div class="intro"><div><h1>Счёт Капибара Коинов</h1></div><span class="tag">КК · Капибара Коины</span></div><div class="account-layout"><aside class="panel children-panel"><h2>Выберите ребёнка <small id="child-count" class="muted" style="float:right;font-size:10px;font-weight:400"></small></h2><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Поиск по фамилии или имени" aria-label="Поиск по ФИО" value="'+esc(query)+'"></div><div class="child-list" id="child-list"></div></aside><div id="profile"></div></div>';listChildren();profile();$('#search').addEventListener('input',e=>{query=e.target.value;listChildren()})}else if(page==='store'){const s=db.showcases.find(s=>s.id===db.published),products=s?s.items.map(id=>db.products.find(p=>p.id===id)).filter(Boolean):[];$('#app').innerHTML='<div class="intro"><div><h1>Витрина товаров</h1><p>Награды за старание и новые открытия.</p></div>'+(s?'<span class="tag store-head"><i class="dot"></i>'+esc(s.name)+'</span>':'')+'</div>'+(products.length?'<section class="store"><div class="store-label">ВЫБЕРИТЕ СВОЮ НАГРАДУ</div><div class="product-grid">'+products.map(productCard).join('')+'</div></section>':'<div class="panel empty">'+(s?'В этой витрине пока нет товаров.':'Витрина пока не опубликована.')+'</div>')}else if(admin)renderAdmin();else{page='account';render()}}
function renderAdmin(){$('#app').innerHTML='<div class="intro"><div><h1>Управление сервисом</h1><p>Товары и витрины</p></div><button class="primary" data-action="'+(adminTab==='products'?'add-product':'add-showcase')+'">+ '+(adminTab==='products'?'Добавить товар':'Добавить витрину')+'</button></div><div class="admin-tabs"><button data-tab="products" class="'+(adminTab==='products'?'active':'')+'">Товары</button><button data-tab="showcases" class="'+(adminTab==='showcases'?'active':'')+'">Витрины</button></div><div id="admin-content"></div>';if(adminTab==='products')$('#admin-content').innerHTML=db.products.length?'<div class="panel"><table class="table"><thead><tr><th>Товар</th><th>Стоимость</th><th>Количество</th><th></th></tr></thead><tbody>'+db.products.map(p=>'<tr><td><span class="tiny-art">'+art(p)+'</span>'+esc(p.name)+'</td><td>'+p.price+' КК</td><td>'+p.quantity+' шт.</td><td><button class="secondary" data-edit-product="'+p.id+'">Открыть</button></td></tr>').join('')+'</tbody></table></div>':'<div class="panel empty">Товаров пока нет. Добавьте первый товар.</div>';else{const live=db.showcases.find(s=>s.id===db.published);$('#admin-content').innerHTML='<h2 style="font-size:15px">Опубликованная витрина</h2>'+(live?showcaseRow(live,true):'<div class="panel empty">Нет опубликованной витрины</div>')+'<div class="divider">Другие витрины</div>'+db.showcases.filter(s=>s.id!==db.published).map(s=>showcaseRow(s,false)).join('')+(db.showcases.every(s=>s.id===db.published)?'<div class="empty">Других витрин пока нет</div>':'')}}
function showcaseRow(s,live){return '<div class="showcase-row '+(live?'live':'')+'"><div><h3>'+esc(s.name)+'</h3><p>'+s.items.length+' товаров'+(live?' · Опубликована':' · Не опубликована')+'</p></div><div class="row-actions"><button class="secondary" data-edit-showcase="'+s.id+'">Редактирование</button><button class="danger" data-delete-showcase="'+s.id+'">Удалить витрину</button>'+(live?'':'<button class="primary" data-publish="'+s.id+'">Опубликовать</button>')+'</div></div>'}
function modal(title,body,wide=false){$('#modal').classList.toggle('wide',wide);$('#modal-content').innerHTML='<div class="modal-head"><h2>'+esc(title)+'</h2><button class="close" data-close aria-label="Закрыть">×</button></div>'+body;if(!$('#modal').open)$('#modal').showModal()}
function login(){modal('Вход для администратора','<form id="login-form"><label for="login">Логин</label><input id="login" name="login" autocomplete="username" required><label for="password">Пароль</label><input id="password" name="password" type="password" autocomplete="current-password" required><div class="error" id="login-error" role="alert"></div><p class="note">Демо-вход: <strong>admin / admin</strong><br>Подключение существующего входа — на следующем этапе.</p><div class="form-actions"><button type="button" class="secondary" data-close>Отмена</button><button class="primary">Войти</button></div></form>');$('#login-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('login')==='admin'&&f.get('password')==='admin'){admin=true;page='admin';$('#modal').close();render()}else $('#login-error').textContent='Неверный логин или пароль.'}}
function editProduct(id){if(!admin)return;const p=db.products.find(p=>p.id===id)||{name:'',description:'',price:0,quantity:0,image:'',art:'plush'};modal(id?'Карточка товара':'Новый товар','<form id="product-form"><label for="product-name">Название</label><input id="product-name" name="name" maxlength="80" required value="'+esc(p.name)+'"><label for="description">Описание</label><textarea id="description" name="description" rows="3" maxlength="300" required>'+esc(p.description)+'</textarea><div class="form-row"><div><label for="price">Стоимость в КК</label><input id="price" name="price" type="number" min="0" step="1" max="1000000" required value="'+p.price+'"></div><div><label for="quantity">Количество, шт.</label><input id="quantity" name="quantity" type="number" min="0" step="1" max="1000000" required value="'+p.quantity+'"></div></div><label for="image">Изображение товара</label><input id="image" type="file" accept="image/png,image/jpeg,image/webp"><div class="note">PNG, JPG или WebP, до 3 МБ.</div><div id="image-preview" class="tiny-art" style="height:100px;margin-top:10px">'+art(p)+'</div><div class="error" id="product-error" role="alert"></div><div class="form-actions">'+(id?'<button type="button" class="danger" data-delete-product="'+id+'">Удалить</button>':'')+'<button type="button" class="secondary" data-close>Отмена</button><button class="primary">Сохранить</button></div></form>');let image=p.image,reading=false;$('#image').onchange=async e=>{const f=e.target.files[0];if(!f)return;$('#product-error').textContent='';if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>3*1024*1024){$('#product-error').textContent='Выберите PNG, JPG или WebP размером до 3 МБ.';e.target.value='';return}reading=true;try{image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});$('#image-preview').innerHTML=art({...p,image})}catch{$('#product-error').textContent='Не удалось загрузить изображение.'}finally{reading=false}};$('#product-form').onsubmit=e=>{e.preventDefault();if(reading){$('#product-error').textContent='Дождитесь загрузки изображения.';return}const f=new FormData(e.target),name=f.get('name').trim(),description=f.get('description').trim();if(!name||!description){$('#product-error').textContent='Заполните название и описание.';return}const product={...p,id:id||'p'+crypto.randomUUID(),name,description,price:Number(f.get('price')),quantity:Number(f.get('quantity')),image};if(mutate(d=>{const i=d.products.findIndex(p=>p.id===product.id);if(i>=0)d.products[i]=product;else d.products.push(product)})){$('#modal').close();render();toast('Товар сохранён')}}}
function editShowcase(id){if(!admin)return;const s=db.showcases.find(s=>s.id===id);editingShowcase=id||null;draftItems=s?[...s.items]:[];modal(s?'Редактирование витрины':'Новая витрина','<form id="showcase-form"><label for="showcase-name">Название витрины</label><input id="showcase-name" maxlength="80" required value="'+esc(s?.name||'')+'"><p class="note">Перенесите товары кнопками + и − или перетащите их между областями.</p><div class="transfer"><div class="transfer-zone" id="all-products" data-zone="all"></div><div class="transfer-zone target" id="selected-products" data-zone="selected"></div></div><div class="error" id="showcase-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary" data-close>Отмена</button><button class="primary">Сохранить витрину</button></div></form>',true);renderTransfer();document.querySelectorAll('[data-zone]').forEach(z=>{z.ondragover=e=>e.preventDefault();z.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(!db.products.some(p=>p.id===id))return;transfer(id,z.dataset.zone==='selected')}});$('#showcase-form').onsubmit=e=>{e.preventDefault();const name=$('#showcase-name').value.trim();if(!name){$('#showcase-error').textContent='Введите название витрины.';return}if(mutate(d=>{const obj={id:editingShowcase||'s'+crypto.randomUUID(),name,items:[...draftItems]};const i=d.showcases.findIndex(s=>s.id===obj.id);if(i>=0)d.showcases[i]=obj;else d.showcases.push(obj)})){$('#modal').close();render();toast('Витрина сохранена')}}}
function renderTransfer(){const item=(p,chosen)=>'<div class="transfer-item" draggable="true" data-drag="'+p.id+'"><span>'+esc(p.name)+'<small class="muted" style="display:block;margin-top:4px">'+p.price+' КК · '+p.quantity+' шт.</small></span><button type="button" data-transfer="'+p.id+'" data-add="'+!chosen+'" aria-label="'+(chosen?'Убрать':'Добавить')+' '+esc(p.name)+'">'+(chosen?'−':'+')+'</button></div>';const available=db.products.filter(p=>!draftItems.includes(p.id)),chosen=draftItems.map(id=>db.products.find(p=>p.id===id)).filter(Boolean);$('#all-products').innerHTML='<h3>Все товары · '+available.length+'</h3>'+available.map(p=>item(p,false)).join('')+(!available.length?'<div class="empty">Все товары перенесены</div>':'');$('#selected-products').innerHTML='<h3>Товары для витрины · '+chosen.length+'</h3>'+chosen.map(p=>item(p,true)).join('')+(!chosen.length?'<div class="empty">Перенесите товары сюда</div>':'');document.querySelectorAll('[data-drag]').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.drag))}
function transfer(id,add){if(add&&!draftItems.includes(id))draftItems.push(id);if(!add)draftItems=draftItems.filter(x=>x!==id);renderTransfer()}
function confirmAction(title,message,fn){modal(title,'<p>'+esc(message)+'</p><div class="form-actions"><button class="secondary" data-close>Отмена</button><button class="danger" id="confirm-action">Удалить</button></div>');$('#confirm-action').onclick=()=>{if(fn()){$('#modal').close();render()}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close')){$('#modal').close();return}if(b.dataset.page){page=b.dataset.page;render();return}if(b.dataset.child){selected=Number(b.dataset.child);listChildren();profile();return}if(!admin)return;if(b.dataset.tab){adminTab=b.dataset.tab;render();return}if(b.dataset.action==='add-product')editProduct();if(b.dataset.action==='add-showcase')editShowcase();if(b.dataset.editProduct)editProduct(b.dataset.editProduct);if(b.dataset.editShowcase)editShowcase(b.dataset.editShowcase);if(b.dataset.transfer)transfer(b.dataset.transfer,b.dataset.add==='true');if(b.dataset.publish){if(mutate(d=>d.published=b.dataset.publish)){render();toast('Витрина опубликована. Предыдущая перемещена в другие витрины.')}}if(b.dataset.deleteProduct){const id=b.dataset.deleteProduct,p=db.products.find(p=>p.id===id);confirmAction('Удалить товар?',p.name+' будет удалён из списка товаров и всех витрин.',()=>mutate(d=>{d.products=d.products.filter(p=>p.id!==id);d.showcases.forEach(s=>s.items=s.items.filter(x=>x!==id))}))}if(b.dataset.deleteShowcase){const id=b.dataset.deleteShowcase,s=db.showcases.find(s=>s.id===id);confirmAction('Удалить витрину?',s.name+(id===db.published?' будет удалена. Опубликованной витрины не останется.':' будет удалена. Товары сохранятся.'),()=>mutate(d=>{d.showcases=d.showcases.filter(s=>s.id!==id);if(d.published===id)d.published=null}))}});
$('#admin-entry').onclick=()=>{if(admin&&page!=='admin'){page='admin';render()}else if(admin){admin=false;page='account';render();toast('Вы вышли из админской части')}else login()};
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('storage',e=>{if(e.key==='capybara-demo-v1'&&e.newValue){try{const next=JSON.parse(e.newValue);if(Array.isArray(next.products)&&Array.isArray(next.showcases)){db=next;render();if($('#modal').open){$('#modal').close();toast('Данные обновлены в другой вкладке. Откройте карточку заново.')}}}catch{}}});
render();
